mapper.select:
SELECT id, novel_id, chapter_id, chapter_no, chapter_title, chunk_no, content, token_count, created_at,
       embedding <=> #{embedding, typeHandler=com.colin.novelanalysis.infrastructure.persistence.handler.PgVectorTypeHandler} AS distance
FROM knowledge_chunk
WHERE novel_id = #{novelId}
ORDER BY embedding <=> #{embedding, typeHandler=com.colin.novelanalysis.infrastructure.persistence.handler.PgVectorTypeHandler}
LIMIT #{topK}
